import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/tes3')
from h import *
X=[]
def G(g,l): return [(g,x) for x in l]
X.append(r(9940851,"Coliflor asada vegana con ajo y parmesano","¡Esta coliflor asada vegana con ajo y parmesano es muy sencilla de hacer e increíblemente sabrosa! ¡Solo 6 ingredientes!","4 porciones","1 porción",
["6 tazas de floretes de coliflor (aprox. 1 coliflor pequeña o media coliflor grande)","2 dientes de ajo picados","1.5 cucharadas de vinagre balsámico","1 cucharada de jugo de limón","¼ de cucharadita de sal marina","3 cucharadas de queso parmesano vegano",("Opcional","perejil fresco para servir"),("Opcional","aderezo ranch vegano para mojar")],
["Precaliente el horno a 425° F/218° C en asar con convección y forre una bandeja para hornear con papel pergamino.","Use un cuchillo afilado para cortar la coliflor en floretes pequeños del tamaño de un bocado y colóquelos en un tazón grande.","En un tazón pequeño, combine el ajo, el vinagre, el jugo de limón y la sal. Luego vierta la mezcla sobre la coliflor y mezcle bien para cubrir las piezas de manera uniforme.","Acomode la coliflor en la bandeja preparada en una sola capa con bastante espacio entre cada pieza. Ase durante 10 minutos y saque del horno para espolvorear con el queso parmesano vegano. Luego, devuelva al horno otros 6 a 8 minutos, hasta que esté dorada."],
["Corte los floretes de coliflor en piezas del mismo tamaño (lo mejor que pueda) para una cocción uniforme. Asegúrese de acomodar la coliflor en una sola capa con bastante espacio entre cada pieza. Esto acelerará el tiempo de cocción y dará como resultado bordes más crujientes. Si no tiene horno con convección, siga las mismas instrucciones, pero puede que necesite agregar unos minutos de tiempo de asado. Esta coliflor asada vegana sabe mejor recién hecha, pero las sobras se conservan en el refrigerador de 3 a 4 días."],[]))
X.append(r(9942188,"Zanahorias y espárragos asados","Una guarnición sencilla con zanahorias y espárragos asados que combina bien con cualquier comida.","6 porciones","1 porción",
["1 libra de espárragos (aprox. 1 manojo)","1 libra de zanahorias (aprox. 6 a 8 zanahorias medianas)","1 cucharada de jugo de limón","1 cucharadita de ajo en polvo","1 cucharadita de semillas de ajonjolí","½ cucharadita de sal marina o al gusto"],
["Precaliente el horno a 400° F/204° C y forre una bandeja grande para hornear con papel pergamino. (O use dos si no tiene una muy grande.)","Corte los extremos de los espárragos y pele las zanahorias. Luego corte las zanahorias en cuartos a lo largo si son de grosor mediano. Si sus zanahorias son muy gruesas, rebánelas para que tengan aprox. el mismo grosor que los espárragos para una cocción uniforme.","Acomode las verduras en la bandeja en una sola capa. Luego rocíelas con jugo de limón y espolvoree con los condimentos.","Hornee durante 20 minutos y luego voltee. Después continúe horneando otros 5 a 10 minutos o hasta alcanzar el punto de cocción deseado. (El tiempo de horneado variará según el grosor de las verduras.)"],
["Rebane las zanahorias muy delgadas (aprox. del mismo grosor que los espárragos) para una cocción uniforme.","Si sus zanahorias son mucho más gruesas que los espárragos y le cuesta cortarlas lo bastante delgadas, hornee las zanahorias 10 a 15 minutos antes de agregar los espárragos."],[]))
X.append(r(9950861,"Hummus de betabel","¡Este hermoso hummus de betabel es un aperitivo perfecto con verduras y galletas saladas O una excelente cobertura para hamburguesas! ¡Su vibrante color y delicioso sabor son insuperables!","6 porciones (rinde aprox. 2 tazas)","1 porción",
["2 betabeles pequeños pelados y en cuartos","1 lata de 15 onzas de garbanzos, escurridos y enjuagados","2 dientes de ajo pelados","2 cucharadas de vinagre balsámico","2 cucharadas de semillas de ajonjolí","2 cucharadas de jugo de limón","¼ de taza de agua, más 1 a 2 cucharadas si es necesario para una consistencia más líquida","½ cucharadita de sal marina"],
["Agregue los betabeles a una cacerola pequeña cubiertos con agua y lleve a hervor, cocinando hasta que estén tiernos al pincharlos con un tenedor, aprox. 20 minutos.","Agregue los betabeles y todos los demás ingredientes a un procesador de alimentos y procese hasta integrar, deteniéndose para raspar los lados según sea necesario.","Sirva con pan pita, verduras o galletas saladas, ¡disfrute!"],
["Rinde aprox. 2 tazas. Guarde las sobras en un recipiente hermético en el refrigerador hasta por 5 días."],[]))
X.append(r(9952260,"Nueces pecanas confitadas estilo tocino","¡Las nueces pecanas confitadas estilo tocino, crujientes, ahumadas, saladas y dulces, también conocidas como trocitos de tocino vegano, son apetitosamente deliciosas e increíblemente adictivas! Querrá espolvorear estos trocitos crujientes sobre ABSOLUTAMENTE TODO.","8 porciones","1 porción",
["1 taza de mitades de nuez pecana","3 cucharadas de tamari o salsa de soya (si no evita el gluten)","¼ de taza de azúcar de coco o azúcar morena","2 cucharaditas de pimentón ahumado","⅛ de cucharadita de pimienta negra (opcional pero recomendada)"],
["Coloque una hoja de papel pergamino sobre una bandeja o la encimera.","Luego coloque las nueces pecanas en un procesador de alimentos y pulse de 7 a 8 veces para triturarlas. No necesitan ser del mismo tamaño y asegúrese de no procesar de más. Quiere trozos grandes, no migajas. Reserve.","Ahora combine todo, excepto las nueces pecanas, en una sartén pequeña y cocine a fuego medio, revolviendo con frecuencia de 2 a 3 minutos. La mezcla debe burbujear; entonces agregue los trozos de nuez pecana. Mezcle bien, cocinando otros 2 a 3 minutos hasta que las nueces estén cubiertas de manera uniforme.","Retire del fuego y extiéndalas sobre el papel pergamino. Déjelas enfriar, luego sepárelas y guárdelas en un recipiente o frasco.",
("Ideas para usar sus nueces pecanas confitadas estilo tocino (opcional)","Hotcakes salados"),("Ideas para usar sus nueces pecanas confitadas estilo tocino (opcional)","Papas al horno, puré de papa, poutine, papas caseras (¡todas las papas!)"),("Ideas para usar sus nueces pecanas confitadas estilo tocino (opcional)","Ensalada Cobb")],
["Tenga cuidado de no procesar de más las nueces pecanas. Solo pulse hasta que se trituren y revíselas con frecuencia. ¡No quiere migajas! Prepare sus trocitos de tocino vegano con anticipación para que tengan oportunidad de enfriarse antes de consumirlos. Una tanda no dura mucho, así que si quiere hacer algunos para congelar, ¡duplique la receta! 😉 Guarde las sobras en un frasco o recipiente hermético a temperatura ambiente hasta por 1 semana, o en el refrigerador de 2 a 3 semanas. Congele en recipiente hermético durante 2 meses. Receta inspirada en Fifteen Spatulas"],[]))
X.append(r(9956832,"Totopos de pita en freidora de aire","Los totopos de pita en freidora de aire son un refrigerio sencillo y delicioso que está listo en menos de 10 minutos.","2 porciones","1 porción",
["2 panes pita integrales o de su elección","1 cucharada de aquafaba o aceite de su elección, si lo prefiere","½ cucharadita de ajo en polvo","½ cucharadita de perejil seco","¼ de cucharadita de sal marina"],
["Corte los panes pita en 8 triángulos. Usar un cortador de pizza es una manera rápida de hacerlo. Luego combine los demás ingredientes en un tazón pequeño.","Barnice la mezcla de especias sobre la parte superior de los triángulos de pita. Luego acomódelos en la canasta de la freidora de aire. (No importa si se traslapan un poco.)","Cocine en la freidora de aire a 350° F/176° C de 3 a 4 minutos para totopos más suaves O de 5 a 7 minutos para totopos más crujientes. Revíselos con frecuencia y retírelos cuando alcancen el punto deseado. ¡Disfrute!"],
["Los diferentes modelos de freidora de aire cocinan a distintas velocidades. Revise los totopos con frecuencia, empezando a los 3 minutos. Para totopos más suaves, cocine en la freidora de aire aprox. de 3 a 4 minutos.","Para totopos crujientes, cocine en la freidora de aire aprox. de 5 a 7 minutos.","No hay problema si los triángulos de pita se traslapan un poco en la canasta de la freidora. Sin embargo, no los traslape por completo. Trabaje por tandas, si es necesario. NOTA: Las tandas posteriores se cocinarán más rápido."],[]))
X.append(r(9957284,"Peras en freidora de aire","¡Peras en freidora de aire dulces, suaves, acarameladas e increíblemente deliciosas! Convierta sus peras maduras en un postre saludable que toda la familia amará.","2","1 porción",
["2 peras Bartlett maduras","1.5 cucharadas de jarabe de arce","1 cucharadita de canela","⅛ de cucharadita de nuez moscada",("Coberturas opcionales","granola"),("Coberturas opcionales","hojuelas de coco"),("Coberturas opcionales","nueces pecanas o nueces de Castilla picadas")],
["Lave y pele las peras. (O puede dejarles la cáscara si lo prefiere.) Luego córtelas en cuartos, raspe las semillas y retire el corazón. Colóquelas en un tazón pequeño para mezclar.","Agregue el jarabe de arce, la canela y la nuez moscada encima y mezcle suavemente, hasta cubrirlas de manera uniforme.","Coloque con una cuchara las peras cubiertas en una sola capa en la canasta y cocine en la freidora de aire a 380 grados F (190 C) de 8 a 12 minutos hasta que estén doradas y acarameladas. ¡No las vierta de golpe!","Retire con cuidado las peras de la canasta y sirva cubiertas con granola, hojuelas de coco y nueces pecanas o nueces de Castilla picadas. Disfrute."],
["Use peras maduras para obtener los resultados más dulces y jugosos. Trate de cortar las rebanadas de pera en piezas del mismo tamaño para una cocción uniforme. Si algunas piezas son más grandes, no quedarán tan suaves, aunque igual de deliciosas. No vierta las peras de golpe en la canasta. Colóquelas con una cuchara con cuidado para evitar que se rompan y acomódelas en una sola capa. Si le sobra marinada en el fondo del tazón, resérvela para glasear las peras una vez cocidas. En el improbable caso de que le sobre, colóquelas en un recipiente sellado en el refrigerador de 2 a 3 días."],[]))
X.append(r(9957667,"Sopa de calabaza butternut en Instant Pot (o en estufa)","¡Sopa de calabaza butternut en Instant Pot cremosa, reconfortante y absolutamente apetitosa!","6 porciones","1 porción",
["1 cebolla amarilla en cubos","1 zanahoria grande pelada y en cubos","1 tallo grande de apio en cubos","2 libras de calabaza butternut pelada y cortada en cubos de 1 pulgada (aprox. 5 tazas en cubos)","1 libra de papas amarillas peladas y cortadas en cubos de 1 pulgada (aprox. 2 tazas en cubos)","1 manzana granny smith grande cortada en trozos, sin corazón ni semillas","5 tazas de caldo de verduras bajo en sodio","½ cucharadita de nuez moscada molida","¼ de cucharadita de jengibre molido","¼ de cucharadita de canela molida","1 taza de leche de nuez de la India sin azúcar o la leche de su elección","sal y pimienta al gusto",("Opcional","crema de nuez de la India para decorar")],
G("Instrucciones para Instant Pot",["Seleccione la función de saltear en la Instant Pot y agregue la cebolla, la zanahoria y el apio con 2 a 3 cucharadas de agua. Saltee hasta que se ablanden, aprox. 5 minutos.","Agregue todos los demás ingredientes, excepto la leche, y revuelva. Cierre la tapa y coloque la válvula en la posición de sellado. Ahora programe para cocinar a presión durante 6 minutos (tardará unos 15 minutos en alcanzar la presión). Cuando termine el temporizador, libere rápidamente la válvula de vapor y abra la tapa cuando sea seguro hacerlo.","Use una licuadora de inmersión para hacer puré la sopa. (O pásela con cuidado a una licuadora de vaso, trabajando por tandas.) Incorpore la leche vegetal y agregue sal y pimienta al gusto. Luego sirva decorada con crema de nuez de la India si lo desea."])+
G("Instrucciones para la estufa",["Agregue la cebolla, la zanahoria y el apio con 2 a 3 cucharadas de agua a una olla grande y saltee hasta que se ablanden, aprox. 5 minutos.","Agregue todos los demás ingredientes, excepto la leche, y mezcle bien. Lleve a hervor y luego reduzca el fuego a fuego lento y cocine hasta que la calabaza y las papas estén tiernas al pincharlas con un tenedor, aprox. de 20 a 25 minutos.","Apague el fuego y haga puré la sopa con una licuadora de inmersión. (O pásela con cuidado a una licuadora de vaso, trabajando por tandas.) Incorpore la leche vegetal y agregue sal y pimienta al gusto. Luego sirva decorada con crema de nuez de la India si lo desea."]),
["Para darle más profundidad de sabor (y si el tiempo lo permite), parta la calabaza butternut por la mitad y áselas con el lado de la pulpa hacia abajo hasta que se pueda atravesar fácilmente con un tenedor. Luego agregue la calabaza asada a la olla de sopa y haga puré todo junto. Para ahorrar tiempo, puede comprar calabaza butternut ya cortada en su supermercado. Necesitará aprox. 5 tazas de calabaza en cubos. Para que no lleve nueces, use leche de soya, leche de avena o leche de coco (de la que viene en cartón, no enlatada) en lugar de la de nuez de la India. Las sobras se conservan refrigeradas de 3 a 5 días en un recipiente sellado o congeladas en un recipiente hermético apto para congelador hasta por 3 meses."],[]))
X.append(r(9959942,"¡Cacahuates en freidora de aire en tres sabores! [sin aceite]","Tres fantásticos sabores de cacahuates en freidora de aire que saben como si estuvieran tostados, pero son mucho más rápidos de hacer.","4 porciones","1 porción",
["1 taza de cacahuates crudos sin sal","1 cucharada de aquafaba o aceite de sabor neutro",
("Cacahuates tostados con sal y pimienta","½ cucharadita de sal marina"),("Cacahuates tostados con sal y pimienta","⅛ de cucharadita de pimienta negra"),
("Cacahuates tostados con BBQ ahumado","½ cucharadita de pimentón ahumado"),("Cacahuates tostados con BBQ ahumado","¼ de cucharadita de ajo en polvo"),("Cacahuates tostados con BBQ ahumado","¼ de cucharadita de sal marina"),("Cacahuates tostados con BBQ ahumado","⅛ de cucharadita de pimienta negra"),
("Cacahuates tostados con sabor a churros","1 cucharadita de azúcar de coco o azúcar morena"),("Cacahuates tostados con sabor a churros","½ cucharadita de canela")],
["Coloque los cacahuates crudos en la canasta de la freidora de aire en una sola capa y cocine en la freidora de aire a 350° F/177° C de 6 a 8 minutos, mezclando a la mitad del tiempo.","Mientras tanto, agregue la cucharada de aquafaba a un tazón pequeño, junto con la mezcla de especias de su elección. Mezcle bien.","Vierta los cacahuates tostados en el tazón con el condimento y mezcle bien para cubrirlos de manera uniforme. Luego devuélvalos a la canasta y cocine en la freidora de aire otros 2 a 4 minutos, hasta que estén dorados, pero vigile con cuidado para evitar que se quemen.","Luego vierta los cacahuates de la freidora de aire en un tazón y deje enfriar unos minutos antes de disfrutar."],
["No sazone los cacahuates desde el inicio de la cocción, o las especias pueden empezar a quemarse. Si hace varias tandas (como debería, para probar todos los sabores 😉), tenga en cuenta que las tandas posteriores se cocinarán un poco más rápido, así que vigile con cuidado. La información nutricional representa una porción de ¼ de taza de los cacahuates de la freidora de aire con sabor a sal y pimienta. Guarde las sobras en un recipiente sellado a temperatura ambiente hasta por 1 semana."],[]))
X.append(r(9964071,"Galletas veganas de calabacita [avena]","Suaves, masticables y llenas de verduras, ¡estas galletas veganas de calabacita son imperdibles!","24 galletas","1 porción",
G("Ingredientes húmedos",["3 plátanos maduros machacados (1 ¼ de taza machacados)","⅓ de taza de crema de cacahuate natural (lisa o con trozos)","¼ de taza de jarabe de arce","2 tazas de calabacita rallada (aprox. 1 calabacita mediana; exprímala para quitar el exceso de humedad)"])+
G("Ingredientes secos",["1 taza de avena en hojuelas (sin gluten, si lo prefiere)","¼ de taza de semillas de cáñamo peladas","¼ de taza de semillas de linaza o linaza molida","1 cucharadita de canela","1 cucharadita de polvo para hornear"]),
["Machaque los plátanos en un tazón grande para mezclar. Luego agregue la crema de cacahuate y el jarabe de arce y mezcle bien. Después, agregue los ingredientes secos y mezcle hasta integrar. La masa será espesa.","Incorpore la calabacita rallada al mismo tazón y deje reposar la masa 10 minutos.","Precaliente el horno a 350° F/176° C y forre una bandeja grande para hornear con papel pergamino.","Luego coloque cucharadas de masa sobre la bandeja y dé forma y aplane las galletas, ya que no se extenderán mucho en el horno.","Hornee de 18 a 22 minutos hasta que estén doradas. Luego sáquelas del horno y déjelas enfriar de 5 a 10 minutos para que se asienten."],
["Para niños exigentes, pele la calabacita antes de rallarla para ocultar su cáscara verde brillante. Exprima la calabacita rallada sobre un tazón o el fregadero antes de agregarla a la masa. La masa será espesa, pero la calabacita agregará humedad a las galletas. Para que no lleven nueces, use crema de soya o de semillas de girasol en lugar de crema de cacahuate. Las galletas sobrantes se conservan a temperatura ambiente 2 días, o refrigeradas hasta por 6 días. Congélelas en un recipiente hermético hasta por 3 meses DESPUÉS de enfriarlas primero a temperatura ambiente."],[]))
X.append(r(9964694,"Crema fresca vegana (también conocida como crème fraîche vegana)","Solo necesita 4 ingredientes y 5 minutos para una cremosa y deliciosa crema fresca vegana (también conocida como crème fraîche) para verter sobre ABSOLUTAMENTE TODO.","8 porciones","1 porción",
["1 taza de nueces de la India crudas","½-3/4 de taza de agua fresca (a mí me gusta media taza más 2 cucharadas)","¼ de taza de jugo de limón verde (aprox. 1 limón grande o 2 pequeños)","½ cucharadita de sal marina"],
["Agregue todos los ingredientes a una licuadora de alta velocidad, como una Vitamix, y procese hasta obtener una mezcla suave y cremosa. Comience con media taza de agua y agregue más de 1 a 2 cucharadas a la vez hasta alcanzar la consistencia deseada. (Me parece que media taza más dos cucharadas es perfecto.)","Sirva con elote, nachos, tacos, sopas o chile, o sobre una ensalada."],
["Si no tiene una licuadora de alta velocidad, remoje las nueces de la India en agua hirviendo durante 30 minutos y luego escúrralas antes de licuar. El tiempo de remojo las ablandará, lo que facilita triturarlas. Refrigere la crema antes de usarla, ya que sabe mejor fría. Si el tiempo no lo permite, igual sabe muy bien recién hecha. Para que no lleve nueces, puede sustituir las nueces de la India por semillas de girasol crudas o pepitas con resultados similares. Asegúrese de usarlas sin sal u omita la sal. Las sobras se conservan refrigeradas hasta por 5 días, o congeladas hasta por 3 meses."],[]))
X.append(r(9966381,"Ensalada vegana de frijoles","¡Una ensalada vegana de frijoles abundante y apetitosamente deliciosa!","6 porciones","1 porción",
G("Para la ensalada",["1 lata de 15 onzas de garbanzos, escurridos y enjuagados (aprox. 1.5 tazas)","1 lata de 15 onzas de frijoles negros, escurridos y enjuagados (aprox. 1.5 tazas)","1 lata de 15 onzas de frijoles rojos, escurridos y enjuagados (aprox. 1.5 tazas)","1.5 tazas de pepino en cubos (aprox. medio pepino largo)","¼ de taza de cebolla morada en cubos","1 aguacate en cubos","½ taza de hojas de albahaca finamente picadas"])+
G("Para el aderezo",["¼ de taza de jugo de limón (aprox. 1 limón mediano)","2 cucharadas de vinagre balsámico","1 cucharada de jarabe de arce","sal y pimienta al gusto"]),
["Escurra y enjuague los frijoles, pique todas las verduras y agréguelas a un tazón grande.","En otro tazón pequeño, combine los ingredientes del aderezo para ensalada. Luego vierta el aderezo sobre la ensalada y mezcle bien para cubrir de manera uniforme. Disfrute de inmediato o refrigere durante 1 hora antes de servir."],
["Planee preparar el platillo aprox. 1 hora antes de servir, ya que sabe mejor frío.","Esta ensalada sabe mejor el mismo día en que se prepara, pero las sobras se conservan en el refrigerador de 2 a 3 días."],[]))
X.append(r(9966537,"Licuado saludable de plátano y nuez","Este licuado de plátano y nuez de Castilla, lleno de proteína, es la manera perfecta de comenzar su mañana, ¡o de darle ese impulso tan necesario por la tarde!","2 porciones","1 porción",
["2 tazas de leche de almendra sin azúcar o la leche de su elección","⅓ de taza de nueces de Castilla","2 plátanos congelados","¼ de cucharadita de canela"],
["Agregue todos los ingredientes a la licuadora y procese hasta obtener una mezcla suave. ¡Disfrute!"],
["No lo sustituya por plátano fresco a menos que sea absolutamente necesario. El plátano congelado funciona mucho mejor. Si no tiene plátanos congelados, puede pelar y rebanar plátanos frescos y congelarlos de 30 a 60 minutos. Asegúrese de rebanarlos primero para ayudar a que se congelen más rápido. Para usar plátanos frescos, si de verdad no tiene tiempo de congelarlos, agregue también un puñado de cubos de hielo al licuado para obtener resultados similares. Asegúrese de que los plátanos estén MUY maduros. Aquí todo el dulzor viene de los plátanos, así que cuanto más maduros, mejor. Elija plátanos con cáscara con manchas marrones antes de congelarlos. Para un licuado más dulce, puede agregar una cucharadita de jarabe de arce puro o 2 a 3 dátiles sin hueso. Si no tiene nueces de Castilla, puede sustituirlas por almendras, avellanas o nueces pecanas. Para obtener los mejores resultados, use una licuadora de alta velocidad, pero si no tiene una, remoje las nueces unos 10 a 15 minutos en agua fresca y luego escúrralas. Esto facilitará que su licuadora las procese, sin dejar granulosidad. Rinde aprox. 3.5 tazas."],[]))
X.append(r(9967440,"Salsa casera para enchiladas","La salsa casera para enchiladas está lista en 15 minutos, ¡así que podrá despedirse de la enlatada para siempre! Es picante, es deliciosa, ¡es FÁCIL!","2 tazas","4 cucharadas",
["1 a 3 jalapeños muy finamente picados","2 tazas de caldo de verduras bajo en sodio","4 cucharadas de pasta de tomate","1 cucharadita de ajo en polvo","1 cucharadita de chile en polvo","1 cucharadita de comino","½ cucharadita de sal marina","1 cucharada de fécula de maíz para espesar, OPCIONAL"],
["Agregue el jalapeño con una o dos cucharadas de caldo a una cacerola pequeña y saltee durante 2 minutos.","Agregue todos los demás ingredientes, mezcle bien y lleve a hervor. Luego reduzca el fuego a medio-bajo y cocine a fuego lento durante 8 minutos hasta que se reduzca un poco.","Use en sus platillos mexicanos favoritos."],
["Use de 1 a 3 jalapeños según su nivel de picante. Si desea una salsa más suave, use 1 jalapeño y quítele las semillas. Para picante medio, use de 1 a 2 con las semillas. Para picante fuerte, use 3 jalapeños con sus semillas. Guarde las sobras en un recipiente sellado o frasco en el refrigerador hasta por 5 días. O puede congelar hasta por 1 mes. Puede licuar la salsa una vez cocida, si lo prefiere. Pero si picó los jalapeños muy finamente, no es necesario. La fécula de maíz opcional funciona bien si usa la salsa de inmediato, tal cual. Si va a agregar la salsa a mi Cazuela de enchiladas de verduras, omita la fécula de maíz. La información nutricional es para ⅛ de la salsa, aprox. 4 cucharadas o ¼ de taza."],[]))
X.append(r(9968027,"Nachos de yaca deshebrada con salsa BBQ casera","Deliciosos nachos veganos cubiertos con yaca bañada en deliciosa salsa BBQ casera. ¡Listos en 20 minutos!","4 porciones","1 porción",
G("Para la yaca",["1 bolsa de 220 gramos de totopos multigrano o de su elección","1 lata de 20 oz de yaca verde joven, escurrida y enjuagada (de la que viene en agua o salmuera, no en almíbar)","3 cucharadas de pasta de tomate","¼ de taza de vinagre de manzana","1 cucharada de jarabe de arce","1 cucharadita de mostaza amarilla","2 cucharadas de tamari o salsa de soya (o ½ cucharadita de sal)","¼ de taza de agua","2 cucharaditas de cebolla en polvo","2 cucharaditas de ajo en polvo","½ cucharadita de pimentón ahumado","¼ de cucharadita de pimienta de cayena (opcional)"])+
G("Coberturas y dips opcionales",["frijoles negros","elote","jalapeño","aceitunas","cilantro fresco","guacamole","crema de nuez de la India","salsa","salsa de queso sin nueces","dip picante de \"jalapeño popper\""]),
["Combine todos los ingredientes de la salsa BBQ en un tazón mediano y mezcle bien. Reserve.","Deshebre los trozos de yaca con las manos o dos tenedores. Se deshebrará con bastante facilidad; colóquela en una sartén grande. Luego vierta la salsa encima y mezcle bien.","A fuego medio, cocine la yaca en la salsa; al principio estará un poco aguada, pero absorberá rápidamente la salsa al cocinarse. Esto tardará unos 5 a 8 minutos.","Mientras tanto, acomode los totopos en capas en un platón para servir y, cuando esté lista, cubra con la yaca y las coberturas de su elección. Sirva sus nachos de yaca con guacamole, crema de nuez de la India y/o salsa."],
["Asegúrese de comprar yaca enlatada en agua o salmuera, y no en almíbar. La de almíbar es muy dulce y lo que se busca es que absorba el sabor de la salsa BBQ, y no que el sabor del almíbar la domine. Si tiene poco tiempo, o no quiere hacer su propia salsa BBQ, puede sustituirla por una salsa comprada. Use unos ¾ de taza de salsa preparada en lugar de la versión casera. Si prefiere algunos bordes crujientes en la yaca, pásela, una vez cocida, a una bandeja para hornear en una sola capa y hornee a 375 grados de 15 a 20 minutos antes de agregarla a los nachos. Para totopos sin aceite, aquí hay una receta de Sweet Simple Vegan para hacer sus propios totopos de tortilla saludables. Recuerde, la yaca es la estrella del platillo, así que agregue una capa generosa sobre los totopos antes de espolvorear coberturas adicionales. Si le sobra, guárdela en un recipiente sellado en el refrigerador hasta por 5 días. Use las sobras para hacer un sándwich vegano estilo \"carne de cerdo deshebrada\" cubierto con mi cremosa ensalada de col vegana."],[]))
